  - discriminate H.
  - cbn [outPassAux]. destruct (outPassStep ls rs) as [[ls' rs'] |] eqn:Hs; [| discriminate H].
    eapply progress_evstep_trans;
      [exact (outPassStep_base_sound _ _ _ _ rb Hs) | apply outPassAux_base_star].
Qed.

