Module M137Certs.
Import M137 M137Ext M137Sec56.

(* ========================================================================= *)
(* 7. Compact Hex Tries, MINI1 Shards, and Acyclic DAG Verifier              *)
(* ========================================================================= *)

Definition checkMiniIdxG (gm : N -> option (N * N)) (fuel : nat) (mid : N) : bool :=
  match gm mid with
  | None => true
  | Some (inN, outN) => checkMiniPair fuel inN outN
  end.

Fixpoint checkMiniRangeG (gm : N -> option (N * N)) (fuel : nat) (lo : N) (cnt : nat) : bool :=
  match cnt with
  | 0 => true
  | S cnt' => andb (checkMiniIdxG gm fuel lo) (checkMiniRangeG gm fuel (lo + 1)%N cnt')
  end.

Lemma checkMiniRangeG_sound : forall gm fuel cnt lo,
  checkMiniRangeG gm fuel lo cnt = true ->
  forall mid, (lo <= mid)%N -> (mid < lo + N.of_nat cnt)%N ->
    match gm mid with
    | None => True
    | Some p => TailBounce (expandL (decN (fst p))) (expandL (decN (snd p)))
    end.
Proof.
  intros gm fuel cnt. induction cnt as [| cnt' IH]; intros lo H mid Hlo Hhi.
  - cbn [N.of_nat] in Hhi. lia.
  - cbn [checkMiniRangeG] in H. apply andb_true_iff in H. destruct H as [H1 H2].
    destruct (mid =? lo)%N eqn:Heq.
    + apply N.eqb_eq in Heq. subst mid.
      unfold checkMiniIdxG in H1.
      destruct (gm lo) as [[inN outN] |]; [exact (checkMiniPair_sound _ _ _ H1) | exact I].
    + apply N.eqb_neq in Heq.
      rewrite Nat2N.inj_succ in Hhi.
      apply (IH (lo + 1)%N H2 mid); lia.
Qed.

Fixpoint runDagCodeG
    (gp : N -> option (list PAtom))
    (gm : N -> option (N * N))
    (gr : N -> option (N * N * N))
    (myId : N) (fuel : nat) (cur accN code : N) : option (N * N) :=
  match fuel with
  | 0 => if (code =? 0)%N then Some (cur, accN) else None
  | S fuel' =>
    if (code =? 0)%N then Some (cur, accN)
    else
      let (tag, r0) := splitBits 2 code in
      if (tag =? 1)%N then
        let (mid, next) := splitBits 12 r0 in
        match gm mid with
        | Some (inN, outN) =>
          if (cur =? inN)%N then runDagCodeG gp gm gr myId fuel' outN (accN + 1)%N next
          else None
        | None => None
        end
      else if (tag =? 2)%N then
        let (pid, r1) := splitBits 8 r0 in
        let (rid, next) := splitBits 11 r1 in
        if (rid <? myId)%N then
          match gp pid with
          | None => None
          | Some ps =>
            match stripAtomsN ps cur, gr rid with
            | Some rem, Some (inN, outN, rN) =>
              if (rem =? inN)%N then
                match joinAtomsN ps outN with
                | Some out' => runDagCodeG gp gm gr myId fuel' out' (accN + rN)%N next
                | None => None
                end
              else None
            | _, _ => None
            end
          end
        else None
      else if (tag =? 3)%N then
        let (rid, r1) := splitBits 11 r0 in
        let (ex, next) := splitBits 24 r1 in
        if (rid <? myId)%N then
          match stripRunN ex cur, gr rid with
          | Some rem, Some (inN, outN, rN) =>
            if (rem =? inN)%N then
              match pushRunN ex outN with
              | Some out' => runDagCodeG gp gm gr myId fuel' out' (accN + rN)%N next
              | None => None
              end
            else None
          | _, _ => None
          end
        else None
      else
        let (mid, r1) := splitBits 12 r0 in
        let (ex, next) := splitBits 24 r1 in
        match stripRunN ex cur, gm mid with
        | Some rem, Some (inN, outN) =>
          if (rem =? inN)%N then
            match pushRunN ex outN with
            | Some out' => runDagCodeG gp gm gr myId fuel' out' (accN + 1)%N next
            | None => None
            end
          else None
        | _, _ => None
        end
  end.

Lemma runDagCodeG_sound : forall gp gm gr myId
  (Hmini : forall mid p, gm mid = Some p ->
    TailBounce (expandL (decN (fst p))) (expandL (decN (snd p))))
  (Hprev : forall rid, (rid < myId)%N -> forall inN outN rN,
    gr rid = Some (inN, outN, rN) ->
    TailBounces rN (expandL (decN inN)) (expandL (decN outN)))
  fuel cur accN code cur' accN',
  runDagCodeG gp gm gr myId fuel cur accN code = Some (cur', accN') ->
  exists dn : N, accN' = (accN + dn)%N /\
    TailBounces dn (expandL (decN cur)) (expandL (decN cur')).
Proof.
  intros gp gm gr myId Hmini Hprev fuel.
  induction fuel as [| fuel' IH]; intros cur accN code cur' accN' H; cbn [runDagCodeG] in H.
  - destruct (code =? 0)%N; [| discriminate H].
    injection H as <- <-. exists 0%N. split; [lia | apply tb_zero].
  - destruct (code =? 0)%N.
    + injection H as <- <-. exists 0%N. split; [lia | apply tb_zero].
    + destruct (splitBits 2 code) as [tag r0].
      destruct (tag =? 1)%N.
      * destruct (splitBits 12 r0) as [mid next].
        destruct (gm mid) as [[inN outN] |] eqn:Hm; [| discriminate H].
        destruct (cur =? inN)%N eqn:Hcur; [| discriminate H].
        apply N.eqb_eq in Hcur. subst cur.
        destruct (IH _ _ _ _ _ H) as [dn2 [Hdn2 Htb2]].
        pose proof (Hmini mid (inN, outN) Hm) as Hb1. cbn [fst snd] in Hb1.
        exists (1 + dn2)%N. split; [lia | exact (tb_trans (tb_one Hb1) Htb2)].
      * destruct (tag =? 2)%N.
        -- destruct (splitBits 8 r0) as [pid r1].
           destruct (splitBits 11 r1) as [rid next].
           destruct (rid <? myId)%N eqn:Hlt; [| discriminate H].
           apply N.ltb_lt in Hlt.
           destruct (gp pid) as [ps |] eqn:Hp; [| discriminate H].
           destruct (stripAtomsN ps cur) as [rem |] eqn:Hs; [| discriminate H].
           destruct (gr rid) as [[[inN outN] rN] |] eqn:Hr; [| discriminate H].
           destruct (rem =? inN)%N eqn:Hrem; [| discriminate H].
           apply N.eqb_eq in Hrem. subst rem.
           destruct (joinAtomsN ps outN) as [out' |] eqn:Hj; [| discriminate H].
           destruct (IH _ _ _ _ _ H) as [dn2 [Hdn2 Htb2]].
           pose proof (tailBounces_frame_atoms ps (Hprev rid Hlt inN outN rN Hr)) as Htb1.
           rewrite <- (stripAtomsN_sound _ _ _ Hs), <- (joinAtomsN_sound _ _ _ Hj) in Htb1.
           exists (rN + dn2)%N. split; [lia | exact (tb_trans Htb1 Htb2)].
        -- destruct (tag =? 3)%N.
           ++ destruct (splitBits 11 r0) as [rid r1].
              destruct (splitBits 24 r1) as [ex next].
              destruct (rid <? myId)%N eqn:Hlt; [| discriminate H].
              apply N.ltb_lt in Hlt.
              destruct (stripRunN ex cur) as [rem |] eqn:Hs; [| discriminate H].
              destruct (gr rid) as [[[inN outN] rN] |] eqn:Hr; [| discriminate H].
              destruct (rem =? inN)%N eqn:Hrem; [| discriminate H].
              apply N.eqb_eq in Hrem. subst rem.
              destruct (pushRunN ex outN) as [out' |] eqn:Hj; [| discriminate H].
              destruct (IH _ _ _ _ _ H) as [dn2 [Hdn2 Htb2]].
              pose proof (tailBounces_frame_run ex (Hprev rid Hlt inN outN rN Hr)) as Htb1.
              rewrite <- (stripRunN_sound _ _ _ Hs), <- (pushRunN_sound _ _ _ Hj) in Htb1.
              exists (rN + dn2)%N. split; [lia | exact (tb_trans Htb1 Htb2)].
           ++ destruct (splitBits 12 r0) as [mid r1].
              destruct (splitBits 24 r1) as [ex next].
              destruct (stripRunN ex cur) as [rem |] eqn:Hs; [| discriminate H].
              destruct (gm mid) as [[inN outN] |] eqn:Hm; [| discriminate H].
              destruct (rem =? inN)%N eqn:Hrem; [| discriminate H].
              apply N.eqb_eq in Hrem. subst rem.
              destruct (pushRunN ex outN) as [out' |] eqn:Hj; [| discriminate H].
              destruct (IH _ _ _ _ _ H) as [dn2 [Hdn2 Htb2]].
              pose proof (Hmini mid (inN, outN) Hm) as Hb0. cbn [fst snd] in Hb0.
              pose proof (tb_one (tailBounce_frame_run ex Hb0)) as Htb1.
              rewrite <- (stripRunN_sound _ _ _ Hs), <- (pushRunN_sound _ _ _ Hj) in Htb1.
              exists (1 + dn2)%N. split; [lia | exact (tb_trans Htb1 Htb2)].
Qed.

Definition checkRuleCodeG
    (gp : N -> option (list PAtom))
    (gm : N -> option (N * N))
    (gr : N -> option (N * N * N))
    (myId code : N) : bool :=
  match gr myId with
  | None => false
  | Some (inN, outN, expN) =>
    match runDagCodeG gp gm gr myId 160 inN 0%N code with
    | None => false
    | Some (got, gotN) => andb (got =? outN)%N (gotN =? expN)%N
    end
  end.

Lemma checkRuleCodeG_sound : forall gp gm gr myId code
  (Hmini : forall mid p, gm mid = Some p ->
    TailBounce (expandL (decN (fst p))) (expandL (decN (snd p))))
  (Hprev : forall rid, (rid < myId)%N -> forall inN outN rN,
    gr rid = Some (inN, outN, rN) ->
    TailBounces rN (expandL (decN inN)) (expandL (decN outN))),
  checkRuleCodeG gp gm gr myId code = true ->
  forall inN outN expN, gr myId = Some (inN, outN, expN) ->
    TailBounces expN (expandL (decN inN)) (expandL (decN outN)).
Proof.
  intros gp gm gr myId code Hmini Hprev H inN outN expN Hget.
  unfold checkRuleCodeG in H. set (f := 160) in H. clearbody f. rewrite Hget in H.
  destruct (runDagCodeG gp gm gr myId f inN 0%N code) as [[got gotN] |] eqn:Hr; [| discriminate H].
  apply andb_true_iff in H. destruct H as [Hgot HgotN].
  apply N.eqb_eq in Hgot. apply N.eqb_eq in HgotN. subst got gotN.
  destruct (runDagCodeG_sound gp gm gr myId Hmini Hprev f inN 0%N code outN expN Hr) as [dn [Hdn Htb]].
  replace expN with dn by lia. exact Htb.
Qed.

Lemma rules_all_soundG : forall gp gm gr,
  (forall mid p, gm mid = Some p ->
    TailBounce (expandL (decN (fst p))) (expandL (decN (snd p)))) ->
  (forall rid, (rid < 1334)%N -> exists code : N, checkRuleCodeG gp gm gr rid code = true) ->
  forall rid, (rid < 1334)%N -> forall inN outN expN,
    gr rid = Some (inN, outN, expN) ->
    TailBounces expN (expandL (decN inN)) (expandL (decN outN)).
Proof.
  intros gp gm gr Hmini Hcert rid.
  pattern rid. apply N_strong_ind.
  intros k IH Hk.
  destruct (Hcert k Hk) as [code Hcode].
  apply (checkRuleCodeG_sound gp gm gr k code Hmini); [| exact Hcode].
  intros r Hr. apply IH; lia.
Qed.

Fixpoint checkRuleSeqG
    (gp : N -> option (list PAtom))
    (gm : N -> option (N * N))
    (gr : N -> option (N * N * N))
    (rid : N) (codes : list N) : bool :=
  match codes with
  | [] => true
  | code :: rest => andb (checkRuleCodeG gp gm gr rid code) (checkRuleSeqG gp gm gr (rid + 1)%N rest)
  end.

Lemma checkRuleSeqG_sound : forall gp gm gr codes lo,
  checkRuleSeqG gp gm gr lo codes = true ->
  forall rid, (lo <= rid)%N -> (rid < lo + N.of_nat (length codes))%N ->
    exists code : N, checkRuleCodeG gp gm gr rid code = true.
Proof.
  intros gp gm gr.
  induction codes as [| c cs IH]; intros lo H rid Hlo Hhi.
  - cbn [length N.of_nat] in Hhi. lia.
  - cbn [checkRuleSeqG] in H. apply andb_true_iff in H. destruct H as [H1 H2].
    destruct (rid =? lo)%N eqn:Heq.
    + apply N.eqb_eq in Heq. subst rid. exists c. exact H1.
    + apply N.eqb_neq in Heq.
      cbn [length] in Hhi. rewrite Nat2N.inj_succ in Hhi.
      apply (IH (lo + 1)%N H2 rid); lia.
Qed.

Fixpoint chunksLen (chunks : list (list N)) : N :=
  match chunks with
  | [] => 0%N
  | ch :: rest => (N.of_nat (length ch) + chunksLen rest)%N
  end.

Fixpoint checkRuleChunksG
    (gp : N -> option (list PAtom))
    (gm : N -> option (N * N))
    (gr : N -> option (N * N * N))
    (rid : N) (chunks : list (list N)) : bool :=
  match chunks with
  | [] => true
  | ch :: rest =>
    andb (checkRuleSeqG gp gm gr rid ch) (checkRuleChunksG gp gm gr (rid + N.of_nat (length ch))%N rest)
  end.

Lemma checkRuleChunksG_sound : forall gp gm gr chunks lo,
  checkRuleChunksG gp gm gr lo chunks = true ->
  forall rid, (lo <= rid)%N -> (rid < lo + chunksLen chunks)%N ->
    exists code : N, checkRuleCodeG gp gm gr rid code = true.
Proof.
  intros gp gm gr.
  induction chunks as [| ch rest IH]; intros lo H rid Hlo Hhi.
  - cbn [chunksLen] in Hhi. lia.
  - cbn [checkRuleChunksG] in H. apply andb_true_iff in H. destruct H as [H1 H2].
    cbn [chunksLen] in Hhi.
    destruct (rid <? lo + N.of_nat (length ch))%N eqn:Hlt.
    + apply N.ltb_lt in Hlt. exact (checkRuleSeqG_sound gp gm gr ch lo H1 rid Hlo Hlt).
    + apply N.ltb_ge in Hlt. apply (IH (lo + N.of_nat (length ch))%N H2 rid Hlt); lia.
