Definition getPeel (pid : N) : option (list PAtom) := trieGetAux peelTree 128%N pid.

Definition getMini (mid : N) : option (N * N) :=
  if (mid <? 2579)%N then trieGetAux miniTree 2048%N mid else None.

Definition getRule (rid : N) : option (N * N * N) := trieGetAux ruleTree 1024%N rid.

Lemma getMini_lt_of_some : forall mid p,
  getMini mid = Some p -> (mid < 2579)%N.
Proof.
  intros mid p H. unfold getMini in H.
  destruct (mid <? 2579)%N eqn:Hlt; [apply N.ltb_lt, Hlt | discriminate H].
Qed.

