Lemma mini_shard_1 : checkMiniRangeG getMini 320 0%N 430 = true.
Proof. vm_compute. reflexivity. Qed.

Lemma mini_shard_2 : checkMiniRangeG getMini 320 430%N 430 = true.
Proof. vm_compute. reflexivity. Qed.

Lemma mini_shard_3 : checkMiniRangeG getMini 320 860%N 430 = true.
Proof. vm_compute. reflexivity. Qed.

Lemma mini_shard_4 : checkMiniRangeG getMini 320 1290%N 430 = true.
Proof. vm_compute. reflexivity. Qed.

Lemma mini_shard_5 : checkMiniRangeG getMini 320 1720%N 430 = true.
Proof. vm_compute. reflexivity. Qed.

Lemma mini_shard_6 : checkMiniRangeG getMini 320 2150%N 429 = true.
Proof. vm_compute. reflexivity. Qed.

Lemma hmini_all : forall mid p,
  getMini mid = Some p -> TailBounce (expandL (decN (fst p))) (expandL (decN (snd p))).
Proof.
  intros mid p Hm.
  pose proof (getMini_lt_of_some mid p Hm) as Hlt.
  assert (Hmatch : match getMini mid with
                   | None => True
                   | Some q => TailBounce (expandL (decN (fst q))) (expandL (decN (snd q)))
                   end).
  { destruct (mid <? 430)%N eqn:H1;
      [apply N.ltb_lt in H1; apply (checkMiniRangeG_sound getMini 320 430 0%N mini_shard_1 mid);
       [lia | change (N.of_nat 430) with 430%N; lia] | apply N.ltb_ge in H1].
    destruct (mid <? 860)%N eqn:H2;
      [apply N.ltb_lt in H2; apply (checkMiniRangeG_sound getMini 320 430 430%N mini_shard_2 mid);
       [lia | change (N.of_nat 430) with 430%N; lia] | apply N.ltb_ge in H2].
    destruct (mid <? 1290)%N eqn:H3;
      [apply N.ltb_lt in H3; apply (checkMiniRangeG_sound getMini 320 430 860%N mini_shard_3 mid);
       [lia | change (N.of_nat 430) with 430%N; lia] | apply N.ltb_ge in H3].
    destruct (mid <? 1720)%N eqn:H4;
      [apply N.ltb_lt in H4; apply (checkMiniRangeG_sound getMini 320 430 1290%N mini_shard_4 mid);
       [lia | change (N.of_nat 430) with 430%N; lia] | apply N.ltb_ge in H4].
    destruct (mid <? 2150)%N eqn:H5;
      [apply N.ltb_lt in H5; apply (checkMiniRangeG_sound getMini 320 430 1720%N mini_shard_5 mid);
       [lia | change (N.of_nat 430) with 430%N; lia] | apply N.ltb_ge in H5].
    apply (checkMiniRangeG_sound getMini 320 429 2150%N mini_shard_6 mid);
      [lia | change (N.of_nat 429) with 429%N; lia]. }
  rewrite Hm in Hmatch. exact Hmatch.
Qed.

Lemma dag_chunks_ok : checkRuleChunksG getPeel getMini getRule 0%N dag_chunks = true.
Proof. vm_compute. reflexivity. Qed.

Lemma dag_chunks_len : chunksLen dag_chunks = 1334%N.
Proof. vm_compute. reflexivity. Qed.

Lemma hdag_all : forall rid, (rid < 1334)%N ->
  exists code : N, checkRuleCodeG getPeel getMini getRule rid code = true.
Proof.
  intros rid Hlt.
  apply (checkRuleChunksG_sound getPeel getMini getRule dag_chunks 0%N dag_chunks_ok rid); [lia |].
  rewrite dag_chunks_len. lia.
Qed.

Lemma hrules_all : forall rid, (rid < 1334)%N ->
  forall inN outN expN, getRule rid = Some (inN, outN, expN) ->
    TailBounces expN (expandL (decN inN)) (expandL (decN outN)).
Proof.
  exact (rules_all_soundG getPeel getMini getRule hmini_all hdag_all).
Qed.

