  [el_single 0 sep0; el_single 2 sep0; el_run10 1%N; el_single 0 sep0; el_run10 11730945%N;
   el_single 2 sep0; el_run10 386565%N; el_single 0 sep0; el_run10 0%N; el_single 2 sep0;
   el_run10 3884%N; el_single 0 sep0; el_single 2 sep0; el_run10 68%N].

