Lemma expandL_frozenRaw : forall tail,
  expandL (frozenRawHead ++ tail) = expandL (atomsToElem frozenAtoms) ++ prependRepL 2%N (expandL tail).
Proof.
  intros tail.
  assert (Hraw : frozenRawHead ++ tail = frozenPrefix ++ (el_run10 68%N :: tail)) by reflexivity.
  assert (Hatoms : atomsToElem frozenAtoms = frozenPrefix ++ [el_run10 66%N]) by reflexivity.
  rewrite Hraw, Hatoms, !expandL_append, <- app_assoc.
  apply f_equal2; [reflexivity |].
  cbn [expandL].
  rewrite prependRepL_append_eq. cbn [app].
  rewrite <- prependRepL_add. reflexivity.
Qed.

Lemma k1_step_0 : TailBounces 68719476732%N (expandL k1_0) (expandL k1_1).
Proof.
  pose proof (tailBounces_frame_atoms [pa_zr2 0%N] rule_1323) as H.
  assert (Hk0 : k1_0 = atomsToElem [pa_zr2 0%N] ++ el_run10 1%N :: rIn_1323) by reflexivity.
  assert (Hk1 : k1_1 = atomsToElem [pa_zr2 0%N] ++ el_run10 1%N :: rOut_1323) by reflexivity.
  rewrite Hk0, Hk1, !expandL_append. cbn [expandL].
  exact H.
Qed.

Lemma k1_step_1 : TailBounce (expandL k1_1) (expandL k1_2).
Proof. apply (checkMiniBounce_sound 320); vm_compute; reflexivity. Qed.

